const coverFor = (title, era) => { const escapeXml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;'); const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600"><rect width="600" height="600" fill="#111111"/><path d="M0 460L600 120V600H0Z" fill="#ffffff" opacity=".12"/><text x="42" y="64" fill="#ffffff" opacity=".7" font-family="monospace" font-size="18" font-weight="700">' + escapeXml(era.toUpperCase()) + '</text><text x="42" y="470" fill="#ffffff" font-family="monospace" font-size="28" font-weight="700">' + escapeXml(title.toUpperCase()) + '</text></svg>'; return 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg); };

